// mpPyLibBytes —— 解码内嵌引擎；失败返回 nil（调用方据此退非零 · fail-closed）。
func mpPyLibBytes() []byte {
	b, err := base64.RawURLEncoding.DecodeString(mpPyLibB64)
	if err != nil {
		return nil
	}
	return b
}

